if(!um_is_admin_manager()){ header('location:index.php'); exit(); }
alumni_ensure_tables($con);
$automaticGraduateCount = alumni_sync_archived_graduates($con);
function alumni_redirect(){ header('location:alumni-hub.php'); exit(); }
$actor = trim((string)($_SESSION['USERID'] ?? ''));
if($_SERVER['REQUEST_METHOD']==='POST' && !alumni_csrf_valid($_POST['csrf']??'')){$_SESSION['alumni_flash']='Your form expired. Please try again.';alumni_redirect();}
if(isset($_POST['save_alumnus'])){
    $id=trim((string)($_POST['alumniid'] ?? '')); if($id===''){$id=alumni_new_id();}
    $fields=array('fullname','graduationyear','programme','mobile','email','locationtext','occupation','organisation','contactpreference','status'); $data=array(); foreach($fields as $field){$data[$field]=trim((string)($_POST[$field] ?? ''));}
    if($data['fullname']!==''){
        $stmt=mysqli_prepare($con, "INSERT INTO tblalumni(alumniid,fullname,graduationyear,programme,mobile,email,locationtext,occupation,organisation,contactpreference,status,recordedby) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE fullname=VALUES(fullname),graduationyear=VALUES(graduationyear),programme=VALUES(programme),mobile=VALUES(mobile),email=VALUES(email),locationtext=VALUES(locationtext),occupation=VALUES(occupation),organisation=VALUES(organisation),contactpreference=VALUES(contactpreference),status=VALUES(status),updatedat=CURRENT_TIMESTAMP");
        if($stmt){mysqli_stmt_bind_param($stmt,'ssisssssssss',$id,$data['fullname'],$data['graduationyear'],$data['programme'],$data['mobile'],$data['email'],$data['locationtext'],$data['occupation'],$data['organisation'],$data['contactpreference'],$data['status'],$actor); mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $_SESSION['alumni_flash']='Alumni record saved.';}
    } alumni_redirect();
}
if(isset($_POST['save_achievement'])){ $stmt=mysqli_prepare($con,'INSERT INTO tblalumniachievement(alumniid,title,description,achieveddate,recordedby) VALUES(?,?,?,?,?)'); if($stmt){$id=trim((string)$_POST['alumniid']);$title=trim((string)$_POST['title']);$desc=trim((string)$_POST['description']);$date=trim((string)$_POST['achieveddate']);mysqli_stmt_bind_param($stmt,'sssss',$id,$title,$desc,$date,$actor);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_flash']='Achievement added to the alumni record.';} alumni_redirect(); }
if(isset($_POST['save_mentor'])){ $stmt=mysqli_prepare($con,'INSERT INTO tblalumnimentorship(alumniid,expertise,availability,notes,status) VALUES(?,?,?,?,?)'); if($stmt){$id=trim((string)$_POST['alumniid']);$expertise=trim((string)$_POST['expertise']);$availability=trim((string)$_POST['availability']);$notes=trim((string)$_POST['notes']);$status=trim((string)$_POST['status']);mysqli_stmt_bind_param($stmt,'sssss',$id,$expertise,$availability,$notes,$status);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_flash']='Mentorship interest recorded.';} alumni_redirect(); }
if(isset($_POST['save_donation'])){ $stmt=mysqli_prepare($con,'INSERT INTO tblalumnidonation(alumniid,donationtype,amount,currency,pledgeddate,receiveddate,status,notes,recordedby) VALUES(?,?,?,?,?,?,?,?,?)'); if($stmt){$id=trim((string)$_POST['alumniid']);$type=trim((string)$_POST['donationtype']);$amount=(float)$_POST['amount'];$currency=trim((string)$_POST['currency']);$pledged=trim((string)$_POST['pledgeddate']);$received=trim((string)$_POST['receiveddate']);$status=trim((string)$_POST['status']);$notes=trim((string)$_POST['notes']);mysqli_stmt_bind_param($stmt,'ssdssssss',$id,$type,$amount,$currency,$pledged,$received,$status,$notes,$actor);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_flash']='Donation or pledge recorded.';} alumni_redirect(); }
if(isset($_POST['save_event'])){ $eventid=alumni_new_id('EVT');$stmt=mysqli_prepare($con,'INSERT INTO tblalumnievent(eventid,title,eventdate,venue,description,status,recordedby) VALUES(?,?,?,?,?,?,?)');if($stmt){$title=trim((string)$_POST['title']);$date=trim((string)$_POST['eventdate']);$venue=trim((string)$_POST['venue']);$desc=trim((string)$_POST['description']);$status=trim((string)$_POST['status']);mysqli_stmt_bind_param($stmt,'sssssss',$eventid,$title,$date,$venue,$desc,$status,$actor);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_flash']='Old-student event created.';} alumni_redirect(); }
if(isset($_POST['approve_alumnus'])){ $id=trim((string)$_POST['alumniid']);$stmt=mysqli_prepare($con,"UPDATE tblalumni SET status='active',updatedat=CURRENT_TIMESTAMP WHERE alumniid=? AND status='pending'");if($stmt){mysqli_stmt_bind_param($stmt,'s',$id);mysqli_stmt_execute($stmt);$approved=mysqli_stmt_affected_rows($stmt)>0;mysqli_stmt_close($stmt);if($approved){list($smsSent,$smsStatus)=alumni_send_welcome_sms($con,$id);$_SESSION['alumni_flash']='Alumni registration approved.'.($smsSent?' Welcome SMS sent.':($smsStatus==='not_opted_in'?' Welcome SMS was not sent because the alumnus did not opt in to SMS updates.':($smsStatus==='no_valid_phone'?' Welcome SMS was not sent because no valid mobile number was supplied.':' Welcome SMS could not be sent right now.')));}}alumni_redirect(); }
if(isset($_POST['approve_all_pending'])){ $pendingIds=array();$pendingRows=mysqli_query($con,"SELECT alumniid FROM tblalumni WHERE status='pending'");while($pendingRows&&($pendingRow=mysqli_fetch_assoc($pendingRows)))$pendingIds[]=$pendingRow['alumniid'];$result=mysqli_query($con,"UPDATE tblalumni SET status='active',updatedat=CURRENT_TIMESTAMP WHERE status='pending'");$approved=$result?mysqli_affected_rows($con):0;$smsSent=0;foreach($pendingIds as $pendingId){list($sent)=alumni_send_welcome_sms($con,$pendingId);if($sent)$smsSent++;}$_SESSION['alumni_flash']=$approved>0?$approved.' Alumni registration(s) approved. Welcome SMS sent to '.$smsSent.' approved Alumni who opted in.':'There are no pending Alumni registrations to approve.';alumni_redirect(); }
if(isset($_POST['send_sms_campaign'])){
    $selectedYears=$_POST['targetyears']??array();
    if(empty($_POST['allyears']) && empty($selectedYears)){ $ok=false; $campaignMessage='Select at least one graduating year, or choose all approved alumni.'; $campaignId=null; }
    else{ list($ok,$campaignMessage,$campaignId)=alumni_create_sms_campaign($con,$actor,$_POST['messagebody']??'',$selectedYears); }
    $_SESSION['alumni_flash']=$campaignMessage;
    if($ok){ alumni_redirect(); }
    alumni_redirect();
}
$flash=$_SESSION['alumni_flash'] ?? ''; unset($_SESSION['alumni_flash']);
if($flash === '' && $automaticGraduateCount > 0){ $flash = $automaticGraduateCount.' archived graduate record(s) were added to the Alumni Hub for review.'; }
$summary=array('alumni'=>0,'mentors'=>0,'pledges'=>0,'events'=>0); foreach(array('alumni'=>"SELECT COUNT(*) n FROM tblalumni WHERE status='active'",'mentors'=>"SELECT COUNT(*) n FROM tblalumnimentorship WHERE status='available'",'pledges'=>"SELECT COUNT(*) n FROM tblalumnidonation WHERE status='pledged'",'events'=>"SELECT COUNT(*) n FROM tblalumnievent WHERE eventdate>=NOW() AND status='planned'") as $key=>$sql){$r=mysqli_query($con,$sql);$summary[$key]=$r?(int)(mysqli_fetch_assoc($r)['n']??0):0;}
$pendingPerPage=10;$pendingPage=max(1,(int)($_GET['pending_page']??1));$pendingSearch=trim((string)($_GET['pending_search']??''));$allPendingCount=0;$allPendingResult=mysqli_query($con,"SELECT COUNT(*) AS total FROM tblalumni WHERE status='pending'");if($allPendingResult&&($allPendingRow=mysqli_fetch_assoc($allPendingResult)))$allPendingCount=(int)$allPendingRow['total'];$pendingWhere="status='pending'";if($pendingSearch!==''){$pendingSearchEsc=mysqli_real_escape_string($con,$pendingSearch);$pendingWhere.=" AND (fullname LIKE '%$pendingSearchEsc%' OR programme LIKE '%$pendingSearchEsc%' OR mobile LIKE '%$pendingSearchEsc%' OR email LIKE '%$pendingSearchEsc%' OR CAST(graduationyear AS CHAR) LIKE '%$pendingSearchEsc%')";}$pendingCount=0;$pendingCountResult=mysqli_query($con,"SELECT COUNT(*) AS total FROM tblalumni WHERE $pendingWhere");if($pendingCountResult&&($pendingCountRow=mysqli_fetch_assoc($pendingCountResult)))$pendingCount=(int)$pendingCountRow['total'];$pendingPages=max(1,(int)ceil($pendingCount/$pendingPerPage));if($pendingPage>$pendingPages)$pendingPage=$pendingPages;$pendingOffset=($pendingPage-1)*$pendingPerPage;$pendingAlumni=array();$pendingResult=mysqli_query($con,"SELECT * FROM tblalumni WHERE $pendingWhere ORDER BY createdat DESC, fullname ASC LIMIT $pendingPerPage OFFSET $pendingOffset");while($pendingResult&&($pendingRow=mysqli_fetch_assoc($pendingResult)))$pendingAlumni[]=$pendingRow;
$alumni=array();$result=mysqli_query($con,"SELECT * FROM tblalumni WHERE status<>'pending' ORDER BY updatedat DESC, fullname ASC");while($result && ($row=mysqli_fetch_array($result,MYSQLI_ASSOC))){$alumni[]=$row;}
$graduationYears=array();foreach($alumni as $alumniYear){$year=(int)($alumniYear['graduationyear']??0);if($year>=1950&&$year<=2100)$graduationYears[$year]=$year;}krsort($graduationYears);
$events=mysqli_query($con,"SELECT * FROM tblalumnievent ORDER BY eventdate ASC LIMIT 8");
$campaigns=mysqli_query($con,"SELECT * FROM tblalumnismscampaign ORDER BY createdat DESC LIMIT 8");
$recentImpact=mysqli_query($con,"SELECT * FROM (SELECT 'Achievement' AS activitytype, al.fullname, ac.title AS detail, ac.createdat FROM tblalumniachievement ac INNER JOIN tblalumni al ON al.alumniid=ac.alumniid UNION ALL SELECT 'Mentorship', al.fullname, me.expertise, me.createdat FROM tblalumnimentorship me INNER JOIN tblalumni al ON al.alumniid=me.alumniid UNION ALL SELECT 'Giving', al.fullname, CONCAT(dn.donationtype, ' · ', dn.currency, FORMAT(dn.amount,2)), dn.createdat FROM tblalumnidonation dn INNER JOIN tblalumni al ON al.alumniid=dn.alumniid) alumniimpact ORDER BY createdat DESC LIMIT 8");
?>
