ype="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token()); ?>"><input type="hidden" name="campaignid" value="<?php echo alumni_safe($campaign['campaignid']); ?>"><button type="submit">Start / continue</button></form><?php }?></article><?php }}else{?><p class="alumni-empty">No SMS campaign has been created yet.</p><?php }?></div></section><section class="alumni-panel alumni-impact"><div class="alumni-head"><span>Relationship history</span><h2>Recent alumni impact</h2></div><div class="alumni-impact-list"><?php if($recentImpact && mysqli_num_rows($recentImpact)>0){while($impact=mysqli_fetch_array($recentImpact,MYSQLI_ASSOC)){?><article><span class="alumni-impact-icon"><i class="fa <?php echo $impact['activitytype']==='Achievement'?'fa-trophy':($impact['activitytype']==='Mentorship'?'fa-handshake-o':'fa-heart'); ?>"></i></span><div><strong><?php echo alumni_safe($impact['fullname']); ?></strong><p><?php echo alumni_safe($impact['activitytype']); ?>: <?php echo alumni_safe($impact['detail']); ?></p></div><time><?php echo alumni_safe(date('d M Y',strtotime($impact['createdat']))); ?></time></article><?php }}else{ ?><p class="alumni-empty">Activity will appear here when you record an achievement, mentorship offer, or giving pledge.</p><?php } ?></div></section>
