    <?php if($pendingAlumni){foreach($pendingAlumni as $pendingPerson){ ?><tr><td><strong><?php echo alumni_safe($pendingPerson['fullname']); ?></strong><small><?php echo alumni_safe($pendingPerson['email']); ?></small></td><td><?php echo alumni_safe($pendingPerson['graduationyear']); ?></td><td><?php echo alumni_safe($pendingPerson['programme']); ?></td><td><?php echo alumni_safe($pendingPerson['mobile']); ?></td><td><?php echo alumni_safe(date('d M Y, g:i a',strtotime($pendingPerson['createdat']))); ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token()); ?>"><input type="hidden" name="alumniid" value="<?php echo alumni_safe($pendingPerson['alumniid']); ?>"><button class="alumni-approve" name="approve_alumnus">Approve</button></form></td></tr><?php }}else{ ?><tr><td colspan="6">No pending Alumni registration matches this search.</td></tr><?php } ?>
    </tbody></table></div>
    <?php if($pendingPages>1){ ?><nav class="alumni-pagination" aria-label="Pending Alumni pages"><?php if($pendingPage>1){ ?><a href="alumni-hub.php?pending_page=<?php echo $pendingPage-1; ?>&pending_search=<?php echo rawurlencode($pendingSearch); ?>#pending-approvals"><i class="fa fa-angle-left"></i> Previous</a><?php } ?><span>Page <?php echo $pendingPage; ?> of <?php echo $pendingPages; ?></span><?php if($pendingPage<$pendingPages){ ?><a href="alumni-hub.php?pending_page=<?php echo $pendingPage+1; ?>&pending_search=<?php echo rawurlencode($pendingSearch); ?>#pending-approvals">Next <i class="fa fa-angle-right"></i></a><?php } ?></nav><?php } ?>
</section>
<script>(function(){var panel=document.getElementById('pending-approvals'),directory=document.querySelector('.alumni-directory');if(panel&&directory)directory.parentNode.insertBefore(panel,directory);})();</script>
<?php } ?>
<?php
function alumni_person_select($people){
    echo '<label class="alumni-select-field"><span>Select alumnus</span><select class="alumni-person-select" name="alumniid" required><option value="">Choose an alumnus…</option>';
    foreach($people as $person){
        echo '<option value="'.alumni_safe($person['alumniid']).'">'.alumni_safe($person['fullname'].($person['graduationyear']?' · '.$person['graduationyear']: '')).'</option>';
    }
    echo '</select></label>';
}
?>
